with joined as (select s.*, d.stock_qty from store_sales s inner join products d on s.product_id = d.id), latest as (select * from (select *, row_number() over (partition by product_id order by sale_date desc nulls first, id) as rn from joined) x where rn = 1), base as (select id, store_id, sale_date, units, revenue, stock_qty, rn - stock_qty as rn_minus_stock_qty, month(sale_date) as sale_date_month from latest where sale_date > date '2023-06-18' and units between 14 and 22), with_windows as (select *, sum(stock_qty) over (partition by store_id order by stock_qty, id rows between unbounded preceding and current row) as cumulative_stock_qty, sum(sale_date_month) over (partition by store_id order by sale_date_month, id rows between unbounded preceding and current row) as cumulative_sale_date_month, sum(stock_qty) over (partition by store_id order by revenue, id rows between unbounded preceding and current row) as running_stock_qty from base), deduped as (select id, sale_date, units, revenue, stock_qty, rn_minus_stock_qty, sale_date_month, cumulative_stock_qty from (select *, rank() over (partition by store_id order by running_stock_qty) as row_num from with_windows) x where row_num = 1) select case when sale_date_month >= 86 then 'PREMIUM' else 'STANDARD' end as sale_date_month_tier, bit_and(units) as units_bit_and, bit_or(units) as units_bit_or from deduped group by case when sale_date_month >= 86 then 'PREMIUM' else 'STANDARD' end;
